-- Campagne « Mes relances » : relance 1, 2 ou 3 après mon 1er, 2e ou 3e contact (7 j à 6 mois), relance 3 ajoutée.
update public.message_blocks set body = E'{{prenom}}, je tente encore ma chance (sans passer en mode spam, promis 😄)\n\nToujours convaincu que ton profil de {{poste}} a sa place chez nous : top 3 du Product en France, plus de 120 WeFiiTers, 100 % sur Claude Entreprise, {{argument_metier}}, et une évolution vers Lead PM ou référent Data & IA.\n\nLes équipes Data & IA se montent maintenant. Pour nous faire gagner du temps, un emoji suffit :\n✅ ok pour 15 min cette semaine ou la suivante\n⏳ pas le bon timing\n❌ pas un sujet pour moi\n\nCorentin', updated_at = now() where code = 'R2';
insert into public.message_blocks (code, kind, label, body, sort_order) values ('R3', 'relance', 'Relance 3 (après le 3e contact, tracée en 3e contact)', E'{{prenom}}, je clos le dossier, c''est vraiment mon dernier message 🙂\n\nPas de retour de ta part, et je le respecte : soit le timing n''est pas le bon, soit WeFiiT n''est pas un sujet pour toi.\n\nSi un jour tu veux emmener ton parcours de {{poste}} vers le Product à l''ère de l''IA (top 3 en France, plus de 120 WeFiiTers, offres Data & IA en lancement), ma porte reste ouverte.\n\nUn emoji pour que je sache où ranger ton profil :\n✅ on se cale 15 min cette semaine ou la suivante\n⏳ recontacte-moi dans 6 mois\n❌ pas pour moi\n\nCorentin', 27) on conflict (code) do update set body = excluded.body, label = excluded.label, updated_at = now();
update public.campaigns set name = 'Mes relances (1er, 2e, 3e contact)', target = 'a_relancer', filters = '{"keywords":"","states":[0,5,11,13],"sort":"updateDate","order":"desc","scope":"all","maxChecks":300,"titlePrefixes":[],"requirePhone":false,"evaluations":[],"segments":["mes_relances"],"companies":[]}'::jsonb, message = '', updated_at = now() where preset = 'relances';
